item.command:
/bin/bash -lc 'tmp_dir=$(mktemp -d "$TMPDIR/snu-gradadm.XXXXXX") && file="$tmp_dir/page.html" && curl --insecure -fsSL --max-time 40 '"'https://snu.edu.in/admissions/graduate-programs/' -o \""'$file" && node - "$file" <<'"'NODE'
const fs = require('fs');
const html = fs.readFileSync(process.argv[2], 'utf8');
for (const row of html.matchAll(/<tr\\b[\\s\\S]*?<\\/tr>/gi)) {
  const cells = [...row[0].matchAll(/<td\\b[\\s\\S]*?<\\/td>/gi)].map(m => m[0].replace(/<["'^>]*>/g,'"' ').replace(/&nbsp;|&#39;|&amp;/g, m=>({'&nbsp;':' ','&#39;':\"'\",'&amp;':'&'}[m])).replace(/\\s+/g,' ').trim());
  if (cells.length >= 3 && cells.slice(0,3).some(x => /Ph\\.D|M\\.Sc|M\\.A|MS|M\\.F|MBA|Chemical|Civil|Computer|Electrical|Electronics|Mechanical|Chemistry|Life Sciences|Mathematics|Physics|Economics|English|Management|Sociology|International Relations|History|Archaeology/i.test(x))) console.log(JSON.stringify(cells.slice(0,6)));
}
NODE"

